--master_gender
create table if not exists public.master_gender(id bigserial not null,
gender_name varchar(255) not null,
is_active boolean default true,
constraint pk_master_gender_id primary key(id),
constraint uk_master_gender_gender_name unique(gender_name));


--master_role
create table if not exists public.master_role(id bigserial not null,
role_name varchar(255) not null,
is_active boolean default true,
constraint pk_master_role_id primary key(id),
constraint uk_master_role_role_name unique(role_name));


--master_category
create table if not exists public.master_category(id bigserial not null,
category_name varchar(255) not null,
is_active boolean default true,
constraint pk_master_category_id primary key(id),
constraint uk_master_category_category_name unique (category_name)
);


--master_product
create table if not exists public.master_product(id bigserial not null,
product_name varchar(255) not null,
category_id bigint not null,
price numeric(15,2) not null, 
is_active boolean default true,
constraint pk_master_product_id primary key(id),
constraint fk_master_product_category_id foreign key(category_id) references master_category(id),
constraint uk_master_product_product_name unique (product_name)
);



--master_state
create table if not exists public.master_state ( id bigserial not null,
state_code bigint not null,
state_name varchar(255) not null,
is_active boolean default true,
constraint pk_master_state_id primary key(id),
constraint uk_master_state_state_code unique(state_code),
constraint uk_master_state_state_name unique(state_name)
);

select * from master_state;


--master_district
create table if not exists public.master_district ( id bigserial not null,
district_code bigint not null,
district_name varchar(255) not null,
state_id bigint not null,
is_active boolean default true,
constraint pk_master_district_id primary key(id),
constraint uk_master_district_district_code unique(district_code),
constraint fk_master_district_state_id foreign key(state_id) references master_state(id),
constraint uk_master_district_district_name_state_id unique(district_name, state_id)
);

--master_sub_district
create table if not exists public.master_sub_district ( id bigserial not null,
sub_district_code bigint not null,
sub_district_name varchar(255) not null,
district_id bigint not null,
is_active boolean default true,
constraint pk_master_sub_district_id primary key(id),
constraint uk_master_sub_district_sub_district_code unique(sub_district_code),
constraint fk_master_sub_district_district_id foreign key(district_id) references master_district(id),
constraint uk_master_sub_district_sub_district_name_district_id unique(sub_district_name, district_id)
);

--master_village
create table if not exists public.master_village ( id bigserial not null,
village_code bigint not null,
village_name varchar(255) not null,
sub_district_id bigint not null,
is_active boolean default true,
constraint pk_master_village_id primary key(id),
constraint uk_master_village_village_code unique(village_code),
constraint fk_master_village_sub_district_id foreign key(sub_district_id) references master_sub_district(id),
constraint uk_master_village_village_name_sub_district_id unique(village_name, sub_district_id)
);

--user_registration
create table if not exists public.user_registration(id bigserial not null,
first_name varchar(255) not null,last_name varchar(255) not null, role_id integer,
email varchar(100) not null, password varchar(500) not null,
mobile varchar(15) not null, age integer,gender_id integer, created_by bigint, created_date timestamp default now(),
modified_by bigint, modified_date timestamp, is_active boolean default true,
constraint pk_user_registration_id primary key(id),
constraint uk_user_registration_email unique(email),
constraint fk_user_registration_gender_id foreign key(gender_id) references master_gender(id),
constraint fk_user_registration_role_id foreign key(role_id) references master_role(id)
);



