--Authored  by Sahitha on 23-10-2025.
--inventory
create table if not exists public.inventory (
    id bigserial not null,
    product_id bigint not null,
    stock integer not null,
	created_by bigint, created_date timestamp default now(),
    modified_by bigint, modified_date timestamp,
    is_active boolean default true,
    constraint pk_inventory_id primary key (id),
    constraint fk_inventory_product_id foreign key (product_id) references master_product(id)
);


--support_tickets
create table if not exists public.support_tickets (
    id bigserial not null,
    customer_id bigint not null,
    order_id bigint not null,
    subject_id bigint not null,
    description text not null,
    created_by bigint, created_date timestamp default now(),
    modified_by bigint, modified_date timestamp,
    is_active boolean default true,
    constraint pk_support_tickets_id primary key (id),
    constraint fk_support_tickets_customer_id foreign key (customer_id) references customer(id),
    constraint fk_support_tickets_order_id foreign key (order_id) references orders (id),
    constraint fk_support_tickets_subject_id foreign key (subject_id) references master_subject (id)
);

--master_status
create table if not exists public.master_status(id bigserial not null,
status varchar(255) not null,
is_active boolean default true,
constraint pk_master_status_id primary key(id)
);


--orders
create table if not exists public.orders( id bigserial not null,
customer_id bigint not null,
product_id bigint not null,
status_id bigint not null,
order_date timestamp not null,
total numeric(15,2) not null,
created_by bigint, created_date timestamp default now(),
modified_by bigint, modified_date timestamp,
is_active boolean default true,
constraint pk_orders_id primary key(id),
constraint fk_orders_customer_id foreign key (customer_id) references customer(id),
constraint fk_orders_status_id foreign key (status_id) references master_status (id),
constraint fk_orders_product_id foreign key (product_id) references master_product(id)
);



select * from orders;


--master_subject
create table if not exists public.master_subject(
id bigserial not null,
description varchar(255) not null,
is_active boolean default true,
constraint pk_master_subject_id primary key(id),
constraint uk_master_subject_description unique (description)
);

--order_tracking
create table if not exists public.order_tracking(
id bigserial not null,
order_id bigint not null,
status_id bigint not null,
created_by bigint, created_date timestamp default now(),
modified_by bigint, modified_date timestamp,
is_active boolean default true,
constraint pk_order_tracking_id primary key(id),
constraint fk_order_tracking_order_id foreign key(order_id) references orders(id),
constraint fk_order_tracking_status_id foreign key(status_id) references master_status(id)
);






--customer
create table if not exists public.customer(id bigserial not null,
first_name varchar(255) not null,last_name varchar(255) not null,
user_id bigint not null,
mobile varchar(15) not null, age integer,gender_id integer, created_by bigint, created_date timestamp default now(),
modified_by bigint, modified_date timestamp, is_active boolean default true,
constraint pk_customers_id primary key(id),
constraint fk_customers_gender_id foreign key(gender_id) references master_gender(id),
constraint fk_customers_user_id foreign key(user_id) references user_registration(id)
);

