CREATE OR REPLACE FUNCTION fn_reset_identity(p_schema character varying,p_table_name character varying ) 
RETURNS void 
LANGUAGE plpgsql
AS
$$
DECLARE
    row     record;
    v_id integer;
BEGIN
    FOR row IN 
        select table_name,column_name
        from information_schema.columns  where is_identity='YES' and table_schema=p_schema 
        and ((table_name  in (select unnest(string_to_array(p_table_name, ','))))
            or p_table_name='null'
            )order by 1
        
        LOOP
        EXECUTE 'select coalesce(max( '|| quote_ident(row.column_name)|| '),0)+1 from '|| p_schema ||'.' || quote_ident(row.table_name) into v_id;
        execute 'ALTER TABLE '|| p_schema ||'.'  || quote_ident(row.table_name)|| ' ALTER COLUMN '|| quote_ident(row.column_name)|| ' RESTART WITH '|| v_id; 
        RAISE INFO 'ALTER TABLE : %', p_schema ||'.'||quote_ident(row.table_name) || ' : ' || quote_ident(row.column_name)|| ' : ' ||v_id;
    END LOOP;
END;
$$;

